#include <cstddef>
#include <cstdint>
#include <deque>
#include <format>
#include <iostream>
#include <memory>
#include <utility>
#include <vector>

constexpr std::ptrdiff_t frame_bytes = 1280 * 720 * 3;

// Adds up the bytes of pixels copied, so the output shows where copies happen.
struct CopyMeter {
  std::int64_t bytes = 0;
};

// A camera frame whose copy constructor reports to a meter. Moves are free and not counted.
class Frame {
 public:
  Frame(std::int64_t stamp_ns, CopyMeter& meter)
      : stamp_ns_(stamp_ns), pixels_(static_cast<std::size_t>(frame_bytes)), meter_(&meter) {}
  Frame(const Frame& other) : stamp_ns_(other.stamp_ns_), pixels_(other.pixels_), meter_(other.meter_) {
    meter_->bytes += std::ssize(pixels_);
  }
  Frame& operator=(const Frame&) = delete;  // not needed here
  Frame(Frame&&) noexcept = default;
  Frame& operator=(Frame&&) noexcept = default;
  ~Frame() = default;

  void mark() { pixels_.front() = 0xff; }
  [[nodiscard]] std::int64_t stamp_ns() const { return stamp_ns_; }

 private:
  std::int64_t stamp_ns_;
  std::vector<std::uint8_t> pixels_;
  CopyMeter* meter_;  // borrowed: the meter outlives every frame
};

[[nodiscard]] Frame watermark(Frame frame) {
  frame.mark();
  return frame;
}

[[nodiscard]] std::int64_t by_value(std::int64_t frames) {
  CopyMeter meter;
  std::deque<Frame> queue;
  for (std::int64_t i = 0; i < frames; ++i) {
    const Frame captured(i, meter);
    const Frame marked = watermark(captured);  // copies into the parameter
    queue.push_back(marked);                   // copies into the queue
  }
  return meter.bytes;
}

[[nodiscard]] std::int64_t by_move(std::int64_t frames) {
  CopyMeter meter;
  std::deque<Frame> queue;
  for (std::int64_t i = 0; i < frames; ++i) {
    Frame captured(i, meter);
    Frame marked = watermark(std::move(captured));
    queue.push_back(std::move(marked));
  }
  return meter.bytes;
}

struct SharedRun {
  std::int64_t bytes_copied;
  std::int64_t owners;
};

[[nodiscard]] SharedRun shared(std::int64_t frames) {
  CopyMeter meter;
  std::deque<std::shared_ptr<const Frame>> to_recorder;
  std::deque<std::shared_ptr<const Frame>> to_viewer;
  for (std::int64_t i = 0; i < frames; ++i) {
    const auto marked = std::make_shared<const Frame>(watermark(Frame(i, meter)));
    to_recorder.push_back(marked);  // copies a pointer and counts an owner
    to_viewer.push_back(marked);
  }
  return SharedRun{.bytes_copied = meter.bytes, .owners = to_viewer.front().use_count()};
}

int main() {
  std::cout << std::format("by value: {} bytes copied for 3 frames\n", by_value(3));
  std::cout << std::format("by move:  {} bytes copied for 3 frames\n", by_move(3));
  const auto [bytes, owners] = shared(3);
  std::cout << std::format("shared:   {} bytes copied for 3 frames, {} owners of each frame\n", bytes, owners);
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <format>
#include <iostream>
#include <vector>

constexpr std::ptrdiff_t frame_bytes = 1280 * 720 * 3;
constexpr std::int64_t ticks_per_second = 150;  // one tick is 1/150 s, so 30 Hz and 25 Hz are whole ticks
constexpr std::int64_t camera_period = 5;       // 30 Hz
constexpr std::int64_t recorder_period = 6;     // 25 Hz

struct CopyMeter {
  std::int64_t bytes = 0;
};

class Frame {
 public:
  Frame(std::int64_t stamp_ns, CopyMeter& meter)
      : stamp_ns_(stamp_ns), pixels_(static_cast<std::size_t>(frame_bytes)), meter_(&meter) {}
  Frame(const Frame& other) : stamp_ns_(other.stamp_ns_), pixels_(other.pixels_), meter_(other.meter_) {
    meter_->bytes += std::ssize(pixels_);
  }
  Frame& operator=(const Frame&) = delete;
  Frame(Frame&&) noexcept = default;
  Frame& operator=(Frame&&) noexcept = default;
  ~Frame() = default;

  void mark() { pixels_.front() = 0xff; }
  [[nodiscard]] std::int64_t stamp_ns() const { return stamp_ns_; }

 private:
  std::int64_t stamp_ns_;
  std::vector<std::uint8_t> pixels_;
  CopyMeter* meter_;
};

[[nodiscard]] Frame watermark(Frame frame) {
  frame.mark();
  return frame;
}

void enqueue(std::deque<Frame>& queue, const Frame& frame) { queue.push_back(frame); }

int main() {
  CopyMeter meter;
  std::deque<Frame> queue;
  std::int64_t captured = 0;
  std::int64_t recorded = 0;
  std::ptrdiff_t peak = 0;
  for (std::int64_t tick = 0; tick < 2 * ticks_per_second; ++tick) {
    if (tick % camera_period == 0) {
      const Frame frame(tick * 1'000'000'000 / ticks_per_second, meter);
      const Frame marked = watermark(frame);
      enqueue(queue, marked);
      ++captured;
    }
    peak = std::max(peak, std::ssize(queue));
    if (tick % recorder_period == 0 && !queue.empty()) {
      queue.pop_front();  // stands for writing the frame to disk
      ++recorded;
    }
  }
  std::cout << std::format("captured {}, recorded {}, still queued {}\n", captured, recorded, queue.size());
  std::cout << std::format("pixels copied: {} bytes\n", meter.bytes);
  std::cout << std::format("queue peak: {} frames, {} bytes\n", peak, peak * frame_bytes);
}

