// A FIFO that holds at most `capacity` items; a push into a full queue drops the oldest and counts it.
// Pre: capacity >= 1.
template <typename T>
class DropOldestQueue {
 public:
  explicit DropOldestQueue(std::ptrdiff_t capacity) : capacity_(capacity) {}

  void push(T item) {
    if (std::ssize(items_) == capacity_) {
      items_.pop_front();
      ++dropped_;
    }
    items_.push_back(std::move(item));
  }

  [[nodiscard]] std::optional<T> pop() {
    if (items_.empty()) return std::nullopt;
    T item = std::move(items_.front());
    items_.pop_front();
    return item;
  }

  [[nodiscard]] std::ptrdiff_t size() const { return std::ssize(items_); }
  [[nodiscard]] std::int64_t dropped() const { return dropped_; }

 private:
  std::ptrdiff_t capacity_;
  std::deque<T> items_;
  std::int64_t dropped_ = 0;
};

int main() {
  CopyMeter meter;
  DropOldestQueue<Frame> queue(5);
  std::int64_t captured = 0;
  std::int64_t recorded = 0;
  std::ptrdiff_t peak = 0;
  for (std::int64_t tick = 0; tick < 2 * ticks_per_second; ++tick) {
    if (tick % camera_period == 0) {
      queue.push(watermark(Frame(tick * 1'000'000'000 / ticks_per_second, meter)));
      ++captured;
    }
    peak = std::max(peak, queue.size());
    if (tick % recorder_period == 0 && queue.pop()) ++recorded;
  }
  std::cout << std::format("captured {}, recorded {}, dropped {}, still queued {}\n", captured, recorded,
                           queue.dropped(), queue.size());
  std::cout << std::format("pixels copied: {} bytes\n", meter.bytes);
  std::cout << std::format("queue peak: {} frames, {} bytes\n", peak, peak * frame_bytes);
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <format>
#include <iostream>
#include <limits>
#include <optional>
#include <utility>

constexpr std::ptrdiff_t frame_bytes = 1280 * 720 * 3;
constexpr std::int64_t ticks_per_second = 150;
constexpr std::int64_t camera_period = 5;    // 30 Hz
constexpr std::int64_t recorder_period = 6;  // 25 Hz

// A FIFO that holds at most `capacity` items; a push into a full queue drops the oldest and counts it.
// Pre: capacity >= 1.
template <typename T>
class DropOldestQueue {
 public:
  explicit DropOldestQueue(std::ptrdiff_t capacity) : capacity_(capacity) {}

  void push(T item) {
    if (std::ssize(items_) == capacity_) {
      items_.pop_front();
      ++dropped_;
    }
    items_.push_back(std::move(item));
  }

  [[nodiscard]] std::optional<T> pop() {
    if (items_.empty()) return std::nullopt;
    T item = std::move(items_.front());
    items_.pop_front();
    return item;
  }

  [[nodiscard]] std::ptrdiff_t size() const { return std::ssize(items_); }
  [[nodiscard]] std::int64_t dropped() const { return dropped_; }

 private:
  std::ptrdiff_t capacity_;
  std::deque<T> items_;
  std::int64_t dropped_ = 0;
};

struct Outcome {
  std::int64_t recorded;
  std::ptrdiff_t peak;
  std::int64_t dropped;
};

// Runs the camera and the recorder for `seconds`, queueing frame stamps only, and reports the queue.
[[nodiscard]] Outcome run(std::ptrdiff_t capacity, std::int64_t seconds) {
  DropOldestQueue<std::int64_t> queue(capacity);
  std::int64_t recorded = 0;
  std::ptrdiff_t peak = 0;
  for (std::int64_t tick = 0; tick < seconds * ticks_per_second; ++tick) {
    if (tick % camera_period == 0) queue.push(tick);
    peak = std::max(peak, queue.size());
    if (tick % recorder_period == 0 && queue.pop()) ++recorded;
  }
  return Outcome{.recorded = recorded, .peak = peak, .dropped = queue.dropped()};
}

int main() {
  constexpr std::ptrdiff_t no_bound = std::numeric_limits<std::ptrdiff_t>::max();
  for (const std::ptrdiff_t capacity : {no_bound, std::ptrdiff_t{30}}) {
    const auto [recorded, peak, dropped] = run(capacity, 60);
    std::cout << std::format("{:<10}recorded {}, dropped {}, queue peak {} frames = {} bytes\n",
                             capacity == no_bound ? "no bound" : "bound 30", recorded, dropped, peak, peak * frame_bytes);
  }
}

#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <vector>

// Meant to save a copy: keeps views of the pixels and writes them all at the next flush.
class Recorder {
 public:
  void enqueue(std::span<const std::uint8_t> pixels) { pending_.push_back(pixels); }

  [[nodiscard]] std::int64_t flush() {
    std::int64_t checksum = 0;
    for (const auto pixels : pending_) checksum += pixels.front();  // stands for writing to disk
    pending_.clear();
    return checksum;
  }

 private:
  std::vector<std::span<const std::uint8_t>> pending_;
};

int main() {
  Recorder recorder;
  for (std::uint8_t shade = 1; shade <= 3; ++shade) {
    const std::vector<std::uint8_t> pixels(1024, shade);
    recorder.enqueue(pixels);
  }  // each vector is destroyed here, at the end of its iteration
  std::cout << std::format("checksum {}\n", recorder.flush());
}
